import {Run,clamp,rng} from './core.js';
import {Kitchen} from './scene.js';
import {CircuitPilot} from './pilot.js';
const $=id=>document.getElementById(id);
let run=new Run(40372),kitchen,pilot,phase='ready',auto=true,sound=false,best=0,accumulator=0,last=0,uiTime=0,toastUntil=0,aboutWasRunning=false,seed=40372,audioCtx;
try{best=Number(localStorage.getItem('flyway-best'))||0;sound=localStorage.getItem('flyway-sound')==='true';}catch{}
function save(key,value){try{localStorage.setItem(key,String(value));}catch{}}
function soundState(){$('sound-button').setAttribute('aria-pressed',sound);$('sound-button').setAttribute('aria-label',sound?'Mute sound':'Enable sound');document.querySelector('.sound-slash').hidden=sound;}
function audio(){if(!sound)return;audioCtx??=new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();}
function tone(freq,duration=.1,type='sine',volume=.04,end=freq){if(!sound||!audioCtx)return;const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(freq,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(30,end),audioCtx.currentTime+duration);g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}
function say(text,duration=1600){$('event-toast').textContent=text;$('event-toast').classList.add('show');toastUntil=performance.now()+duration;}
function setMode(value){auto=value;$('auto-button').classList.toggle('selected',value);$('human-button').classList.toggle('selected',!value);$('auto-button').setAttribute('aria-pressed',value);$('human-button').setAttribute('aria-pressed',!value);$('footer-mode').innerHTML=value?'FLY IN CONTROL <i>↗</i>':'HUMAN IN CONTROL <i>↗</i>';$('pilot-label').textContent=value?'Circuit + reflex pilot':'Human pilot · circuit observing';if(phase==='running')say(value?'TINY BRAIN, TAKE THE WHEEL.':'YOUR SIX LEGS NOW.');}
function act(action,human=false){if(phase!=='running')return;if(human&&auto)setMode(false);if(run.input(action)){if(action==='jump')tone(220,.15,'sine',.018,630);if(action==='duck')tone(190,.1,'triangle',.015,90);}}
function start(){if(!kitchen||!pilot)return;audio();seed+=137;run=new Run(seed);pilot.reset();kitchen.reset();phase='running';document.body.classList.add('playing');$('gameover-screen').hidden=true;$('pause-screen').hidden=true;$('pause-button').disabled=false;$('pause-button').setAttribute('aria-label','Pause game');$('pause-button').textContent='Ⅱ';accumulator=0;tone(320,.1,'square',.02,440);setTimeout(()=>tone(640,.17,'square',.02,900),120);say(auto?'RELEASE THE FLY!':'RUN, LITTLE GUY!',1900);renderUI();}
function pause(value){if(phase!=='running'&&phase!=='paused')return;phase=value?'paused':'running';$('pause-screen').hidden=!value;$('pause-button').textContent=value?'▶':'Ⅱ';$('pause-button').setAttribute('aria-label',value?'Resume game':'Pause game');last=performance.now();}
function finish(){phase='ending';$('pause-button').disabled=true;setTimeout(()=>{if(phase!=='ending')return;phase='over';best=Math.max(best,Math.floor(run.distance));save('flyway-best',best);$('result-distance').textContent=Math.floor(run.distance);$('result-sugar').textContent=run.sugar;$('result-best').textContent=best;$('gameover-screen').hidden=false;$('retry-button').focus({preventScroll:true});},700);}
function handleEvents(events){for(const e of events){if(e.type==='sugar'){kitchen.burst(run.x,0);tone(700+(run.sugar%5)*150,.1,'sine',.04,1100+(run.sugar%5)*140);if(run.sugar>0&&run.sugar%20===0)say('SUGAR. RUSH. REPEAT.');}if(e.type==='hit'){kitchen.hit();$('hit-flash').style.opacity=1;setTimeout(()=>$('hit-flash').style.opacity=0,150);tone(120,.27,'sawtooth',.05,40);say(run.hits>=3?'SWAT HAPPENS.':run.hits===2?'THAT SHADOW IS GETTING BIGGER.':'BARELY AN INCONVENIENCE.');}if(e.type==='recover'){say('SOMEHOW, STILL ALIVE.');tone(400,.15,'sine',.04,800);}if(e.type==='end')finish();}}
function renderUI(){const d=Math.floor(run.distance);$('distance').textContent=String(d).padStart(4,'0');$('sugar-count').textContent=run.sugar;$('time').textContent=`${String(Math.floor(run.time/60)).padStart(2,'0')}:${String(Math.floor(run.time%60)).padStart(2,'0')}`;$('best').innerHTML=`${Math.max(best,run.ended?d:0)} <small>m</small>`;$('thought').textContent=phase==='over'||phase==='ending'?'Reconsidering its career choices.':phase==='ready'?'Avoid becoming a wall decoration.':pilot?.thought||'Finding a way through.';$('threat-fill').style.width=`${25+run.hits*29}%`;$('threat-fill').style.background=run.hits===2?'#fa5591':run.hits===1?'#ffc66b':'#d8fc50';$('threat-label').textContent=['A LITTLE TOO CLOSE','PERSONAL SPACE: VIOLATED','EXTREMELY SWATTABLE','SWATTED'][run.hits];for(const el of document.querySelectorAll('[data-key]'))el.classList.toggle('active',el.dataset.key===run.action&&phase==='running');$('brain-state').textContent=phase==='paused'?'PAUSED':phase==='over'?'AT REST':phase==='ready'?'READY':'ACTIVE';}
class BrainView {
 constructor(canvas,graph){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.graph=graph;const rand=rng(27183);this.positions=[];for(let i=0;i<graph.units.count;i++){const side=graph.units.side[i];const sideX=side==='L'?-.48:side==='R'?.48:0;const a=rand()*Math.PI*2,r=Math.sqrt(rand());this.positions.push({x:sideX+Math.cos(a)*r*.44,y:Math.sin(a)*r*.72,z:rand()*.6-.3});}this.links=[];for(let i=0;i<graph.edges.count;i+=90)this.links.push([graph.edges.pre[i],graph.edges.post[i]]);}
 draw(rates,time){const w=this.canvas.clientWidth,h=this.canvas.clientHeight,dpr=Math.min(devicePixelRatio,2);if(this.canvas.width!==w*dpr||this.canvas.height!==h*dpr){this.canvas.width=w*dpr;this.canvas.height=h*dpr;}const ctx=this.ctx;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const c=Math.cos(time*.12)*.1;const pts=this.positions.map(p=>[w/2+(p.x+c*p.z)*w*.43,h/2+p.y*h*.49]);ctx.lineWidth=.35;for(const [a,b]of this.links){const v=Math.max(rates[a],rates[b]);ctx.strokeStyle=`rgba(171,219,141,${.02+Math.min(v,.8)*.13})`;ctx.beginPath();ctx.moveTo(...pts[a]);ctx.lineTo(...pts[b]);ctx.stroke();}let sum=0;for(let i=0;i<pts.length;i++){const v=clamp(rates[i]/2,0,1);sum+=rates[i];ctx.fillStyle=v>.35?`rgba(224,255,114,${.45+v*.55})`:`rgba(138,182,137,${.18+v*.9})`;ctx.beginPath();ctx.arc(pts[i][0],pts[i][1],.6+v*1.2,0,Math.PI*2);ctx.fill();}ctx.font='12px monospace';ctx.fillStyle='#687e61';ctx.fillText('L',6,h-6);ctx.fillText('SCHEMATIC',w/2-32,h-6);ctx.fillText('R',w-12,h-6);$('brain-frequency').textContent=`${(sum/rates.length).toFixed(2)} ACT.`;}
}
let brainView;
function frame(now){requestAnimationFrame(frame);const raw=last?(now-last)/1000:0;const dt=clamp(raw,0,.05);last=now;if(!kitchen||!pilot)return;if(phase==='running'){accumulator+=dt;while(accumulator>=.05){const action=pilot.update(run.observation(),.05,auto);if(auto&&action!=='none')act(action);accumulator-=.05;}handleEvents(run.step(dt));}else if(phase==='ready'){accumulator+=dt;if(accumulator>=.05){pilot.simulate(.055,.055,1);accumulator=0;}}if(phase!=='paused')kitchen.update(run,dt,phase==='ending'?'over':phase);uiTime+=dt;if(uiTime>.065){renderUI();brainView.draw(pilot.rates,now*.001);uiTime=0;}if(now>toastUntil)$('event-toast').classList.remove('show');}
$('start-button').addEventListener('click',start);$('retry-button').addEventListener('click',start);$('auto-button').addEventListener('click',()=>setMode(true));$('human-button').addEventListener('click',()=>setMode(false));$('pause-button').addEventListener('click',()=>pause(phase==='running'));$('resume-button').addEventListener('click',()=>pause(false));$('sound-button').addEventListener('click',()=>{sound=!sound;save('flyway-sound',sound);soundState();audio();tone(660,.1,'sine',.025);});
function showAbout(){aboutWasRunning=phase==='running';if(aboutWasRunning)pause(true);$('about-dialog').showModal();}
$('about-button').addEventListener('click',showAbout);$('model-info').addEventListener('click',showAbout);$('close-about').addEventListener('click',()=>$('about-dialog').close());$('about-dialog').addEventListener('close',()=>{if(aboutWasRunning)pause(false);});$('about-dialog').addEventListener('click',e=>{if(e.target===$('about-dialog')){const b=$('about-dialog').getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)$('about-dialog').close();}});
const keys={ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right',ArrowUp:'jump',w:'jump',W:'jump',' ':'jump',ArrowDown:'duck',s:'duck',S:'duck'};
window.addEventListener('keydown',e=>{if($('about-dialog').open)return;if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if((e.key==='Escape'||e.key.toLowerCase()==='p')&&['running','paused'].includes(phase)){e.preventDefault();if(!e.repeat)pause(phase==='running');return;}if(keys[e.key]&&phase==='running'){e.preventDefault();if(!e.repeat)act(keys[e.key],true);}});
for(const b of document.querySelectorAll('[data-action]'))b.addEventListener('pointerdown',e=>{e.preventDefault();act(b.dataset.action,true);});let touch;
$('game').addEventListener('pointerdown',e=>{touch={x:e.clientX,y:e.clientY};$('game').setPointerCapture(e.pointerId);});$('game').addEventListener('pointerup',e=>{if(!touch)return;const dx=e.clientX-touch.x,dy=e.clientY-touch.y;touch=null;if(Math.max(Math.abs(dx),Math.abs(dy))<20)return;act(Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'duck':'jump',true);});$('game').addEventListener('pointercancel',()=>touch=null);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&phase==='running')pause(true);});
soundState();renderUI();
try{kitchen=new Kitchen($('game'));kitchen.update(run,0,'ready');const response=await fetch('./data/flight-v1.json');if(!response.ok)throw Error('The fly circuit could not be loaded. Reload to try again.');const graph=await response.json();pilot=new CircuitPilot(graph);brainView=new BrainView($('brain'),graph);$('neuron-count').textContent=`${graph.units.count.toLocaleString()} NEURONS`;$('model-description').innerHTML='<p><strong>1,072 neurons. 26,544 connections. One very questionable driver.</strong></p><p>The pilot runs a small, real-connectivity subset of the MaleCNS fly nervous system in your browser. Obstacles become artificial left/right sensory inputs. A simplified recurrent rate model produces the steering signal; hand-coded arcade reflexes handle jumps and ducks.</p><p>This is an experimental game controller, not a complete fly brain or learned gameplay. The panel shows computed activity, with a schematic layout rather than anatomical positions. Activity values are dimensionless.</p>';$('start-button').disabled=false;$('start-button').querySelector('span').textContent='RELEASE THE FLY';$('brain-state').textContent='READY';brainView.draw(pilot.rates,0);requestAnimationFrame(frame);}catch(error){console.error(error);$('error-screen').hidden=false;$('error-message').textContent=error.message?.includes('WebGL')?'This game needs WebGL 2. Try a current browser with hardware acceleration enabled.':error.message;}

